<?php use App\Support\App;App::requireAdmin();$db=App::db();$gw=[];foreach($db->query('SELECT code,is_active FROM payment_gateways')->fetchAll() as $x)$gw[$x['code']]=(int)$x['is_active'];$title='Settings';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';function sv($k,$d=''){return htmlspecialchars((string)App::setting($k,$d));}?><div><h1 class="page-title">System settings</h1><p class="page-sub">Kelola website, provider, payment gateway dan bot tanpa edit .env.</p></div><form id="f" class="space-y-5 mt-6"><section class="settings-grid"><div class="settings-info"><b>General</b><p>Identitas platform dan pendaftaran.</p></div><div class="saas-card p-5 space-y-4"><label class="text-sm font-semibold">Site name<input class="field mt-2" name="site_name" value="<?=sv('site_name','CEKSINYAL')?>"></label><label class="toggle-row"><input type="checkbox" name="registration_enabled" value="1" <?=App::setting('registration_enabled','1')==='1'?'checked':''?>>Registration enabled</label></div></section><section class="settings-grid"><div class="settings-info"><b>CeirGo provider</b><p>Credential server-side untuk service sync dan order.</p></div><div class="saas-card p-5 space-y-4"><label class="text-sm font-semibold">Base URL<input class="field mt-2" name="ceirgo_base_url" value="<?=sv('ceirgo_base_url','https://ceirgo.id')?>"></label><label class="text-sm font-semibold">API Key<input class="field mt-2 font-mono" type="password" name="ceirgo_api_key" value="<?=sv('ceirgo_api_key')?>"></label></div></section><section class="settings-grid"><div class="settings-info"><b>Payment gateways</b><p>Aktifkan metode dan isi credential.</p></div><div class="saas-card p-5 space-y-5"><div class="grid sm:grid-cols-3 gap-3"><?php foreach([['manual','Manual'],['gobiz','GoBiz QRIS'],['jago','Bank Jago']] as $g):?><label class="toggle-row"><input type="checkbox" name="gateway_<?=$g[0]?>" value="1" <?=!empty($gw[$g[0]])?'checked':''?>><?=$g[1]?></label><?php endforeach?></div><div class="border-t pt-4 space-y-3" style="border-color:var(--line)"><b class="text-sm">GoBiz</b><input class="field font-mono" name="gobiz_qr_string" value="<?=sv('gobiz_qr_string')?>" placeholder="Static QRIS string"><input class="field font-mono" type="password" name="gobiz_token" value="<?=sv('gobiz_token')?>" placeholder="Token"><input class="field" name="gobiz_journal_url" value="<?=sv('gobiz_journal_url')?>" placeholder="Journal URL"></div><div class="border-t pt-4 space-y-3" style="border-color:var(--line)"><b class="text-sm">Jago Gmail OAuth</b><input class="field" name="jago_gmail_client_id" value="<?=sv('jago_gmail_client_id')?>" placeholder="Client ID"><input class="field" type="password" name="jago_gmail_client_secret" value="<?=sv('jago_gmail_client_secret')?>" placeholder="Client secret"><input class="field" type="password" name="jago_gmail_refresh_token" value="<?=sv('jago_gmail_refresh_token')?>" placeholder="Refresh token"></div></div></section><section class="settings-grid"><div class="settings-info"><b>WhatsApp Bot</b><p>Koneksi bot dan internal API.</p></div><div class="saas-card p-5 space-y-4"><label class="toggle-row"><input type="checkbox" name="bot_enabled" value="1" <?=App::setting('bot_enabled','1')==='1'?'checked':''?>>Bot enabled</label><input class="field" name="bot_number" value="<?=sv('bot_number')?>" placeholder="628xxxxxxxx"><input class="field" name="bot_api_url" value="<?=sv('bot_api_url')?>" placeholder="Bot API URL"><input class="field font-mono" type="password" name="bot_api_token" value="<?=sv('bot_api_token')?>" placeholder="Internal bot token"></div></section><button class="btn btn-dark"><i data-lucide="save"></i>Save all settings</button></form><script>f.onsubmit=async e=>{e.preventDefault();let fd=new FormData(f),o=Object.fromEntries(fd);for(const k of ['registration_enabled','bot_enabled','gateway_manual','gateway_gobiz','gateway_jago'])o[k]=fd.has(k)?1:0;let r=await fetch('/api/admin/settings',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify(o)}),j=await r.json();Swal.fire(j.ok?'Saved':'Error',j.message||'Settings updated',j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>